#include <Simbody.h>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <cmath>
using namespace SimTK;
int main(int argc,char**argv){if(argc!=2)return 2;std::ofstream out(argv[1]);out<<std::setprecision(17)<<"{\"frames\":[";for(int variant=0;variant<3;variant++){MultibodySystem system;SimbodyMatterSubsystem matter(system);GeneralForceSubsystem forces(system);Force::UniformGravity gravity(forces,matter,Vec3(0,-9.81,0));Body::Rigid body(MassProperties(1.,Vec3(0),Inertia(.05)));MobilizedBody::Pin first(matter.Ground(),Transform(Vec3(0)),body,Transform(Vec3(0,1,0)));MobilizedBody::Pin second(first,Transform(Vec3(0)),body,Transform(Vec3(0,1,0)));system.realizeTopology();State state=system.getDefaultState();first.setOneQ(state,0,.5+.5*variant);second.setOneQ(state,0,-.4);system.realize(state,Stage::Velocity);double initial=system.calcEnergy(state);RungeKuttaMersonIntegrator integrator(system);integrator.setAccuracy(1e-8);TimeStepper stepper(system,integrator);stepper.initialize(state);std::vector<Vec3> trail;double drift=0;for(int n=1;n<=300;n++){stepper.stepTo(n/60.);const State&s=stepper.getState();system.realize(s,Stage::Velocity);drift=std::max(drift,std::abs(system.calcEnergy(s)-initial));trail.push_back(second.getBodyOriginLocation(s));}if(!std::isfinite(drift)||drift>1e-4){std::cerr<<"Energy drift "<<drift;return 3;}const State&s=stepper.getState();Vec3 p=first.getBodyOriginLocation(s),q=second.getBodyOriginLocation(s);auto point=[&](Vec3 v){out<<"["<<v[0]*.43<<","<<(v[1]+.7)*.43<<"]";};if(variant)out<<",";out<<"{\"angle\":"<<.5+.5*variant<<",\"maxEnergyDrift\":"<<drift<<",\"paths\":[{\"color\":\"#496778\",\"points\":[";for(size_t i=0;i<trail.size();i++){if(i)out<<",";point(trail[i]);}out<<"]},{\"color\":\"#57d8c6\",\"points\":[";point(Vec3(0));out<<",";point(p);out<<",";point(q);out<<"]}],\"points\":[";point(p);out<<",";point(q);out<<"],\"radius\":0.035}";std::cout<<variant<<" drift "<<drift<<"\n";}out<<"]}";}
